import{_ as r,l as n,o as e,c as l,v as t,p as E,x as i,d as p,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"vNM 公理怎么用","description":"","frontmatter":{"title":"vNM 公理怎么用","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/vnm-axioms.md","filePath":"econ/vnm-axioms.md","lastUpdated":1789023840000}'),m={name:"econ/vnm-axioms.md"};function d(A,a,u,c,B,b){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="vnm-公理怎么用" tabindex="-1">vNM 公理怎么用 <a class="header-anchor" href="#vnm-公理怎么用" aria-label="Permalink to &quot;vNM 公理怎么用&quot;">​</a></h1><div class="epigraph"><p>把最好与最差当锚，无差异概率就是效用——独立性保证这个概率在任何共同混合里都不改口。</p><footer>—— 据 von Neumann and Morgenstern, Theory of Games and Economic Behavior, 1944 整理</footer></div><p><a href="/econ/expected-utility">上一课</a>已经给出工作表示 \\(U(F)=\\mathbb{E}_F u\\)，并声明 \\(u\\) 在正仿射变换下唯一。本课不重写这条定义，也不把彩票集合再介绍一遍。缺口是：独立性与连续性究竟怎样把「排序」逼成「概率加权」，后课才能知道阿莱打的是证明里的哪一步，而不是打在「人不会算平均数」上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表示定理的结论上一课用过了。证明却有一截没钉死：若只有理性，连续效用在 \\(\\Delta(X)\\) 上仍只是序数的，单调变换合法。要把 \\(U\\) 收成对概率线性，必须让「与最好结果无差异的概率」成为刻度。缺口是把公理当成操作：连续性给出这个概率存在，独立性给出它不随共同混合项改变，于是 \\(U\\) 在复合彩票上仿射。</p><p>设结果有最好 \\(b\\) 与最差 \\(w\\)，对任意 \\(x\\) 存在 \\(\\pi(x)\\) 使 \\(x\\sim \\pi(x)\\,b+(1-\\pi(x))\\,w\\)。定义 \\(u(x)=\\pi(x)\\)。对任意彩票 \\(F\\)，独立性允许把 \\(F\\) 里每个结果换成它的无差异两极混合，再把共同的 \\(b,w\\) 提出来，得到 \\(F\\sim \\bigl(\\mathbb{E}_F u\\bigr)b+\\bigl(1-\\mathbb{E}_F u\\bigr)w\\)。比较两张彩票于是化成比较两个概率。这就是「怎么用」，不是另一套 \\(U\\) 的定义。</p><h3 id="仿射唯一不是序数唯一" tabindex="-1">仿射唯一不是序数唯一 <a class="header-anchor" href="#仿射唯一不是序数唯一" aria-label="Permalink to &quot;仿射唯一不是序数唯一&quot;">​</a></h3><p>若 \\(\\tilde u=au+b\\)、\\(a\\gt 0\\)，期望排序不变。若换成非线性单调变换，概率加权不再保持排序——因为刻度是用概率本身量的。上一课的基数性在本课变成一句可检验的话：测两次无差异概率，只允许差一个正仿射。后课 Arrow–Pratt 要用 \\(u&#39;&#39;/u&#39;\\)，缺了这一步没有不变性。</p><p><span class="marginnote">阿基米德（连续性）排除「无穷好」的结果：再小的概率碰到无穷，无差异概率不存在。独立性排除「共同尾事件仍改排序」。两刀缺一，构造停在半路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工作顺序固定。先用理性把 \\(\\Delta(X)\\) 排好；再用连续性，对夹在中间的 \\(F\\)，解出与两极混合无差异的 \\(\\alpha\\in(0,1)\\)；最后用独立性：对一切 \\(H\\)，</p> \\[F\\sim G \\implies \\alpha F+(1-\\alpha)H\\sim \\alpha G+(1-\\alpha)H, \\]<p>把复合彩票拆成一阶段分布时，权重可加减。于是 \\(U(\\alpha F+(1-\\alpha)G)=\\alpha U(F)+(1-\\alpha)U(G)\\)。线性是推出来的，不是对 \\(\\mathbb{E}u\\) 再写一遍。</p><p>有限支撑时以上足够。无限支撑要补可测与有界，否则积分可以不是连续效用。主干停留在有限结果，与上一课一致。</p>',14)),(e(),E(h,null,{default:i(()=>[s(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAT%5B%22%E7%90%86%E6%80%A7%E6%8E%92%E5%BA%8F%22%5D%20--%3E%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E6%80%A7%EF%BC%9A%E6%97%A0%E5%B7%AE%E5%BC%82%E6%A6%82%E7%8E%87%E5%AD%98%E5%9C%A8%22%5D%0A%20%20CONT%20--%3E%20IND%5B%22%E7%8B%AC%E7%AB%8B%E6%80%A7%EF%BC%9A%E8%AF%A5%E6%A6%82%E7%8E%87%E5%8F%AF%E8%BF%81%E7%A7%BB%22%5D%0A%20%20IND%20--%3E%20AFF%5B%22U%20%E5%9C%A8%E6%B7%B7%E5%90%88%E4%B8%8A%E7%BA%BF%E6%80%A7%22%5D%0A%20%20AFF%20--%3E%20CAL%5B%22u(x)%20%3D%20%E6%97%A0%E5%B7%AE%E5%BC%82%E6%A6%82%E7%8E%87%22%5D%0A%20%20CAL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%97%AE%E5%8D%B7%E6%98%AF%E5%90%A6%E6%8E%A5%E5%8F%97%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课仍用客观概率。状态名字、主观信念不是这里的缺口。也不引入对概率的非线性加权：那是表示已经失败之后的另一条文献。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立性的操作含义是：共同的 \\(H\\) 可以从两边同时删掉，就像线性方程里消去同类项。vNM 证明反复做这件事，直到只剩两极的权重。若决策者把「确定」或「共同的零」当成不能消的质，无差异概率随背景变，\\(u\\) 不再是结果上的函数，仿射表示崩溃——下一课阿莱就是把这步拿去实验。</p><p>连续性的操作含义是：概率轴是连通的，偏好没有跳跃的洞。没有它，只能得到字典式一类的非期望表示，后课的微积分风险厌恶写不下去。两公理分工：连续给实数刻度，独立给加法。</p><p><span class="marginnote">构造里 \\(u(b)=1\\)、\\(u(w)=0\\) 只是归一化，不是「效用有上界」的经济学。换一对锚，等于做一次正仿射变换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假定有最好、最差。结果无界时要用更弱的连续性（如混合连续）加增长条件，教科书常绕开。也不处理模糊：概率未知则无差异概率本身没有客观轴可沿。</p><p>实验偏离不是本课的对象。本课只标明：若接受两公理，表示必仿射；若拒绝独立性，不要再用同一 \\(u\\) 去解释两对问卷。主干后课仍用 \\(\\mathbb{E}u\\)，但会知道自己站在哪一条推演上。</p><p>不要把无差异概率写成限价簿上的成交概率。这里是实验室彩票的权重，不是报价强度。Savage 的主观概率公理更长，本课不走。</p><p>后课默认：vNM 表示的基数性来自「无差异概率可迁移」；检验独立性即检验这一迁移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不重写 \\(\\mathbb{E}u\\)；本课只用独立性与连续性把无差异概率变成刻度。</li><li>连续性保证锚与中间结果之间有概率；独立性保证该概率不随共同混合改变。</li><li>线性与仿射唯一是推出来的，故非线性单调变换不合法。</li><li>下一课阿莱检验的正是「共同项可消去」这一迁移。</li><li>出处：von Neumann and Morgenstern, <em>Theory of Games and Economic Behavior</em>, 1944。</li></ul>',12))])}const x=r(m,[["render",d]]);export{F as __pageData,x as default};
